function insertionShifts(arr) {
  const a = [...arr];
  let shifts = 0;
  for (let i = 1; i < a.length; i++) {
    const key = a[i];
    let j = i - 1;
    while (j >= 0 && a[j] > key) {
      shifts++;
      a[j + 1] = a[j];
      j--;
    }
    a[j + 1] = key;
  }
  return shifts;
}

const sorted = [1, 2, 3, 4, 5];
const random = [5, 3, 7, 1, 4];
const reversed = [5, 4, 3, 2, 1];
console.log('sorted shifts:', insertionShifts(sorted));
console.log('random shifts:', insertionShifts(random));
console.log('reversed shifts:', insertionShifts(reversed));

